SELECT 
FROM TBL_DECISION_RECOMMENDATIONS


        AND ORGID = #{params.orgId}


        AND RECOMMENDATIONNO LIKE CONCAT('%', #{params.recommendationNo}, '%')


        AND RECOMMENDATIONNAME LIKE CONCAT('%', #{params.recommendationName}, '%')


        AND RECOMMENDATIONTYPE = #{params.recommendationType}


        AND RECOMMENDATIONSTATUS = #{params.recommendationStatus}


        AND PRIORITY = #{params.priority}


        AND MODELID = #{params.modelId}


        AND ANALYSISID = #{params.analysisId}


        AND CREATETIME >= #{params.startDate}


        AND CREATETIME <= #{params.endDate}


        AND CONFIDENCELEVEL >= #{params.minConfidence}


        AND CONFIDENCELEVEL <= #{params.maxConfidence}


ORDER BY CREATETIME DESC

SELECT 
FROM TBL_DECISION_RECOMMENDATIONS
WHERE RECOMMENDATIONNO = #{recommendationNo} AND ORGID = #{orgId}

SELECT COUNT(1)
FROM TBL_DECISION_RECOMMENDATIONS
WHERE RECOMMENDATIONNO = #{recommendationNo} AND ORGID = #{orgId}

    AND RECOMMENDATIONID != #{excludeId}

SELECT 
FROM TBL_DECISION_RECOMMENDATIONS
WHERE ORGID = #{orgId}
AND CONFIDENCELEVEL >= #{minConfidence}
ORDER BY CONFIDENCELEVEL DESC

