SELECT COUNT(*) AS totalCount, COUNT(CASE WHEN RECOMMENDATIONSTATUS = 'PENDING' THEN 1 END) AS pendingCount, COUNT(CASE WHEN RECOMMENDATIONSTATUS = 'REVIEWED' THEN 1 END) AS reviewedCount, COUNT(CASE WHEN RECOMMENDATIONSTATUS = 'APPROVED' THEN 1 END) AS approvedCount, COUNT(CASE WHEN RECOMMENDATIONSTATUS = 'REJECTED' THEN 1 END) AS rejectedCount, COUNT(CASE WHEN RECOMMENDATIONSTATUS = 'IMPLEMENTED' THEN 1 END) AS implementedCount, AVG(CONFIDENCELEVEL) AS avgConfidence, MAX(CONFIDENCELEVEL) AS maxConfidence, MIN(CONFIDENCELEVEL) AS minConfidence, COUNT(CASE WHEN PRIORITY = 'HIGH' THEN 1 END) AS highPriorityCount, COUNT(CASE WHEN PRIORITY = 'MEDIUM' THEN 1 END) AS mediumPriorityCount, COUNT(CASE WHEN PRIORITY = 'LOW' THEN 1 END) AS lowPriorityCount FROM TBL_DECISION_RECOMMENDATIONS WHERE ORGID = #{orgId}
AND CREATETIME >= #{startDate}
AND CREATETIME <= #{endDate}

SELECT
    DATE(CREATETIME) AS createDate,
    COUNT(*) AS recommendationCount,
    AVG(CONFIDENCELEVEL) AS avgConfidence,
    COUNT(CASE WHEN RECOMMENDATIONSTATUS = 'IMPLEMENTED' THEN 1 END) AS implementedCount
FROM TBL_DECISION_RECOMMENDATIONS
WHERE ORGID = #{orgId}

    AND RECOMMENDATIONTYPE = #{recommendationType}


    AND CREATETIME >= #{startDate}


    AND CREATETIME <= #{endDate}

GROUP BY DATE(CREATETIME)
ORDER BY createDate ASC

SELECT RECOMMENDATIONTYPE AS recommendationType, COUNT(*) AS totalRecommendations, COUNT(CASE WHEN RECOMMENDATIONSTATUS = 'APPROVED' THEN 1 END) AS approvedRecommendations, COUNT(CASE WHEN RECOMMENDATIONSTATUS = 'IMPLEMENTED' THEN 1 END) AS implementedRecommendations, COUNT(CASE WHEN RECOMMENDATIONSTATUS = 'REJECTED' THEN 1 END) AS rejectedRecommendations, AVG(CONFIDENCELEVEL) AS avgConfidence, ROUND(COUNT(CASE WHEN RECOMMENDATIONSTATUS = 'APPROVED' THEN 1 END) * 100.0 / COUNT(*), 2) AS approvalRate, ROUND(COUNT(CASE WHEN RECOMMENDATIONSTATUS = 'IMPLEMENTED' THEN 1 END) * 100.0 / COUNT(*), 2) AS implementationRate FROM TBL_DECISION_RECOMMENDATIONS WHERE ORGID = #{orgId}
AND CREATETIME >= #{startDate}
AND CREATETIME <= #{endDate}
GROUP BY RECOMMENDATIONTYPE ORDER BY implementationRate DESC

SELECT RECOMMENDATIONID AS recommendationId, RECOMMENDATIONNO AS recommendationNo, RECOMMENDATIONNAME AS recommendationName, RECOMMENDATIONTYPE AS recommendationType, CONFIDENCELEVEL AS confidenceLevel, PRIORITY AS priority, RECOMMENDATIONSTATUS AS recommendationStatus, CREATETIME AS createTime FROM TBL_DECISION_RECOMMENDATIONS WHERE RECOMMENDATIONID IN
#{recommendationId}
ORDER BY CONFIDENCELEVEL DESC

SELECT CREATETIME AS createTime, RECOMMENDATIONNAME AS recommendationName, CONFIDENCELEVEL AS confidenceLevel, RECOMMENDATIONSTATUS AS recommendationStatus, PRIORITY AS priority FROM TBL_DECISION_RECOMMENDATIONS WHERE RECOMMENDATIONTYPE = #{recommendationType} AND ORGID = #{orgId}
AND CREATETIME >= #{startDate}
AND CREATETIME <= #{endDate}
ORDER BY CREATETIME DESC

SELECT 
FROM TBL_DECISION_RECOMMENDATIONS
WHERE ORGID = #{orgId}
AND CONFIDENCELEVEL IS NOT NULL
ORDER BY CONFIDENCELEVEL DESC

    LIMIT #{limit}

SELECT RECOMMENDATIONTYPE AS recommendationType, COUNT(*) AS totalCount, AVG(CONFIDENCELEVEL) AS avgConfidence, COUNT(CASE WHEN CONFIDENCELEVEL >= 85 THEN 1 END) AS highQualityCount, ROUND(COUNT(CASE WHEN CONFIDENCELEVEL >= 85 THEN 1 END) * 100.0 / COUNT(*), 2) AS qualityRate, COUNT(CASE WHEN RECOMMENDATIONSTATUS = 'IMPLEMENTED' THEN 1 END) AS implementedCount FROM TBL_DECISION_RECOMMENDATIONS WHERE ORGID = #{orgId}
AND CREATETIME >= #{startDate}
AND CREATETIME <= #{endDate}
GROUP BY RECOMMENDATIONTYPE ORDER BY qualityRate DESC
